package uk.ac.ravensbourne.casevault.web;
import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import uk.ac.ravensbourne.casevault.service.EvidenceService; import uk.ac.ravensbourne.casevault.security.UserPrincipal;
@RestController @RequestMapping("/cases/{caseId}/evidence") public class EvidenceController { private final EvidenceService evidence; public EvidenceController(EvidenceService e){evidence=e;} @PostMapping public ResponseEntity<Void> upload(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID caseId,@RequestParam("file") MultipartFile f)throws Exception{var saved=evidence.upload(p,caseId,f);return ResponseEntity.created(java.net.URI.create("/cases/"+caseId+"/evidence/"+saved.getId())).build();} @GetMapping("/{id}") public ResponseEntity<byte[]> download(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID caseId,@PathVariable UUID id)throws Exception{byte[] b=evidence.download(p,caseId,id);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename*=UTF-8''evidence-"+URLEncoder.encode(id.toString(),StandardCharsets.UTF_8)).header("X-Content-Type-Options","nosniff").cacheControl(CacheControl.noStore()).body(b);} }
